def _en_href(t):
    for a in ('<a href="/experiences/', '<a href="/faq/', '<a href="/">'):
        t = t.replace(a, a.replace('href="/', 'href="/en/', 1))
    return t
for _k, _v in list(_CONF.items()):
    T_PAGE_ALL[_k] = _v
    if '<a href="/' in _k:
        T_PAGE_ALL[_en_href(_k)] = _en_href(_v)
